                              let (fflags, elem) : (bits_fflags, bits('m)) = match 'm {
                                8  => riscv_f16ToUi8(0b001, vs2_val[i]),
                                16 => riscv_f32ToUi16(0b001, vs2_val[i]),
                                32 => riscv_f64ToUi32(0b001, vs2_val[i])
                              };
                              accrue_fflags(fflags);
                              elem
                            },
        FNV_CVT_RTZ_X_F  => {
                              let (fflags, elem) : (bits_fflags, bits('m)) = match 'm {
