// ****************************** OPFVV (VVMTYPE) *******************************
// FVVM instructions' destination is a mask register
union clause instruction = FVVMTYPE : (fvvmfunct6, bits(1), vregidx, vregidx, vregidx)

mapping encdec_fvvmfunct6 : fvvmfunct6 <-> bits(6) = {
  FVVM_VMFEQ      <-> 0b011000,
  FVVM_VMFLE      <-> 0b011001,
  FVVM_VMFLT      <-> 0b011011,
  FVVM_VMFNE      <-> 0b011100
}

mapping clause encdec = FVVMTYPE(funct6, vm, vs2, vs1, vd)
  <-> encdec_fvvmfunct6(funct6) @ vm @ encdec_vreg(vs2) @ encdec_vreg(vs1) @ 0b001 @ encdec_vreg(vd) @ 0b1010111
  when (currentlyEnabled(Ext_Zvfh)   & get_sew() == 16)
     | (currentlyEnabled(Ext_Zve32f) & get_sew() == 32)
     | (currentlyEnabled(Ext_Zve64d) & get_sew() == 64)

$ifdef SYMBOLIC
function clause execute FVVMTYPE(funct6, vm, vs2, vs1, vd) = {
  let rm_3b    = fcsr[FRM];
  let SEW      = get_sew();
  let LMUL_pow = get_lmul_pow();
  let num_elem = get_num_elem(LMUL_pow, SEW);

  if illegal_fp_vd_unmasked(SEW, rm_3b) |
     not(valid_reg_group(vs1, LMUL_pow)) |
     not(valid_reg_group(vs2, LMUL_pow))
  then return Illegal_Instruction();

  assert(SEW != 8);

  let 'n = num_elem;
  let 'm = SEW;

  let vm_val  : bits('n)             = read_vmask(num_elem, vm, zvreg);
  let vs1_val : vector('n, bits('m)) = read_vreg(num_elem, SEW, LMUL_pow, vs1);
  let vs2_val : vector('n, bits('m)) = read_vreg(num_elem, SEW, LMUL_pow, vs2);
  let vd_val  : bits('n)             = read_vmask(num_elem, 0b0, vd);

  let (initial_result, mask) : (bits('n), bits('n)) = match init_masked_result_cmp(num_elem, SEW, LMUL_pow, vd_val, vm_val) {
    Ok(v)   => v,
    Err(()) => return Illegal_Instruction()
  };
  var result = initial_result;

  var combined_flags : bits_fflags = 0b00000;
  foreach (i from 0 to (num_elem - 1)) {
    let (lane_flags, lane_value) : (bits_fflags, bool) = match funct6 {
        FVVM_VMFEQ       => fp_eq_pure(vs2_val[i], vs1_val[i]),
        FVVM_VMFNE       => fp_ne_pure(vs2_val[i], vs1_val[i]),
        FVVM_VMFLE       => fp_le_pure(vs2_val[i], vs1_val[i]),
        FVVM_VMFLT       => fp_lt_pure(vs2_val[i], vs1_val[i])
    };
    result[i] = masked_select(mask[i], isla_bool_to_bit(lane_value), initial_result[i]);
    combined_flags = combined_flags | ite(mask[i] == 0b1, lane_flags, 0b00000)
  };
  accrue_fflags(combined_flags);

  write_vmask(num_elem, vd, result);
  set_vstart(zeros());
  RETIRE_SUCCESS
}

$else
function clause execute FVVMTYPE(funct6, vm, vs2, vs1, vd) = {
  let rm_3b    = fcsr[FRM];
  let SEW      = get_sew();
  let LMUL_pow = get_lmul_pow();
  let num_elem = get_num_elem(LMUL_pow, SEW);

  if illegal_fp_vd_unmasked(SEW, rm_3b) |
     not(valid_reg_group(vs1, LMUL_pow)) |
     not(valid_reg_group(vs2, LMUL_pow))
  then return Illegal_Instruction();

  assert(SEW != 8);

  let 'n = num_elem;
  let 'm = SEW;

  let vm_val  : bits('n)             = read_vmask(num_elem, vm, zvreg);
  let vs1_val : vector('n, bits('m)) = read_vreg(num_elem, SEW, LMUL_pow, vs1);
  let vs2_val : vector('n, bits('m)) = read_vreg(num_elem, SEW, LMUL_pow, vs2);
  let vd_val  : bits('n)             = read_vmask(num_elem, 0b0, vd);

  let (initial_result, mask) : (bits('n), bits('n)) = match init_masked_result_cmp(num_elem, SEW, LMUL_pow, vd_val, vm_val) {
    Ok(v)   => v,
    Err(()) => return Illegal_Instruction()
  };
  var result = initial_result;

  foreach (i from 0 to (num_elem - 1)) {
    if mask[i] == 0b1 then {
      let res : bool = match funct6 {
        FVVM_VMFEQ    => fp_eq(vs2_val[i], vs1_val[i]),
        FVVM_VMFNE    => ~(fp_eq(vs2_val[i], vs1_val[i])),
        FVVM_VMFLE    => fp_le(vs2_val[i], vs1_val[i]),
        FVVM_VMFLT    => fp_lt(vs2_val[i], vs1_val[i])
      };
      result[i] = bool_to_bit(res)
    }
  };

  write_vmask(num_elem, vd, result);
  set_vstart(zeros());
  RETIRE_SUCCESS
}

